      await p.waitForSelector('#dTabs [data-t="upgrade"]'); await p.waitForTimeout(300); await p.click('#dTabs [data-t="upgrade"]'); await p.waitForTimeout(3000);
      const A1 = await p.evaluate(() => { const U = upgState.pp.U; return { ci: (U.ci || []).join(""), key: U.key, green: [...U.meta.values()].filter(c => (c.ci || []).includes("G")).length }; });
