      await p.evaluate(() => { const d = S.decks.pp; d.format = "casual"; save(); renderDeck(d); }); await p.waitForTimeout(300); if (!(await p.$("#uMode"))) await p.click('#dTabs [data-t="upgrade"]'); await p.waitForTimeout(2500);
      const A3 = await p.evaluate(() => upgState.pp.U.key);
