      ok(v.rows.length && v.rows.every(r => /If replaced:/.test(r.imp) && /Bracket impact not checked yet\./.test(r.imp)), `${label}: every shown swap has an impact block (${v.rows.length})`);
      // Compare: the options can't be applied until their impact is known
