      ok(sh1.n >= 2 && sh1.disabled && sh1.slots.every(t => /Bracket impact not checked yet\./.test(t)), `${label}: in Compare, all ${sh1.n} options say not checked yet, and none can be applied`);
      const deck0 = await p.evaluate(() => JSON.stringify(S.decks.brago.cards));
      await p.click("[data-cpick='1']", { force: true }).catch(() => {}); await p.waitForTimeout(200);
