      release(); await p.waitForFunction(() => document.querySelector("[data-cpick]") && !document.querySelector("[data-cpick]").disabled, null, { timeout: 20000 }); await p.waitForTimeout(300);
      const sh2 = await p.evaluate(() => ({ disabled: [...document.querySelectorAll("[data-cpick]")].some(b => b.disabled), slots: [...document.querySelectorAll("[data-cslot]")].map(e => e.textContent) }));
      ok(!sh2.disabled && sh2.slots.every(t => !/not checked yet/.test(t) && /No new legality problems\./.test(t)), `${label}: once the data arrives, Compare shows each option's result and the options can be applied`);
      await p.evaluate(() => closeSheet()); await p.waitForTimeout(500);
